@layer components {
  .feed-page {
    max-width: var(--shelf-feedPage-maxWidth);
    background-color: var(--shelf-feedPage-bgColor-surface);
    color: var(--shelf-feedPage-fgColor-default);
    padding: var(--shelf-feedPage-space-padding);
  }

  .feed-page-heading {
    font-size: var(--shelf-feedPage-fgColor-heading);
    color: var(--shelf-feedPage-fgColor-heading);
  }

  .feed-item {
    background-color: var(--shelf-feedItem-bgColor-surface);
    border: var(--shelf-feedItem-borderColor-default) solid var(--shelf-feedItem-borderWidth);
    padding: var(--shelf-feedItem-space-padding);
  }

  .feed-item-title {
    color: var(--shelf-feedItem-fgColor-title);
    font-size: var(--shelf-feedItem-fontSize-title);
  }

  .feed-item-description {
    color: var(--shelf-feedItem-fgColor-description);
    font-size: var(--shelf-feedItem-fontSize-description);
  }
}
